AREA bss (RAM,REL)



;-----------------------------------------------
;  EQUATES
;-----------------------------------------------
bPOWERMASK:          equ   03h         ; Power field mask for CR3
LPF_CNUMMASK:        equ   1fh         ; Mask for A, B & C Caps
LPF_CFBMASK:         equ   80h         ; Mask for Feedback Caps
LPF_POLARITYMASK:    equ   20h         ; Mask of Asign field for CR0

LowpassTemporal_IfCond: equ LowpassTemporal_AMD_MSK & 0x01

IF (LowpassTemporal_AMD_VAL)
 IF (LowpassTemporal_IfCond)
  LowpassTemporal_AMD:  equ LowpassTemporal_AMD_VAL
 ELSE
  LowpassTemporal_AMD:  equ LowpassTemporal_AMD_VAL << 4
 ENDIF
ENDIF

AREA UserModules (ROM,REL)
;-----------------------------------------------------------------------------
;  FUNCTION NAME: LowpassTemporal_Start
;
;  DESCRIPTION: Applies power setting to the module's PSoC blocks
;
;-----------------------------------------------------------------------------
;
;  ARGUMENTS:    A register contains the power setting (constant)
;  RETURNS:      Nothing
;  SIDE EFFECTS: 
;    The A and X registers may be modified by this or future implementations
;    of this function.  The same is true for all RAM page pointer registers in
;    the Large Memory Model.  When necessary, it is the calling function's
;    responsibility to perserve their values across calls to fastcall16 
;    functions.
;

 LowpassTemporal_Start:
_LowpassTemporal_Start:
 LowpassTemporal_SetPower:
_LowpassTemporal_SetPower:
    RAM_PROLOGUE RAM_USE_CLASS_2
    and A, bPOWERMASK                        ; mask A to protect unchanged bits
    mov X, SP                                ; define temp store location

    push A                                   ; put power value in temp store

IF (LowpassTemporal_AMD_VAL)
   M8C_SetBank1
   mov   A, reg[LowpassTemporal_AMD_REG]         ; read modulator register
   and   A, ~LowpassTemporal_AMD_MSK             ; clear modulator bittfield in A
   or    A, LowpassTemporal_AMD                  ; combine modulator value with balance of register
   mov   reg[LowpassTemporal_AMD_REG], A         ; move complete value back to register
   M8C_SetBank0
ENDIF

    mov A, reg[LowpassTemporal_FLIN_CR3]    ; read power value
    and A, ~bPOWERMASK                       ; clear power bits in A
    or  A, [X]                               ; combine power value with balance of reg.
    mov reg[LowpassTemporal_FLIN_CR3], A    ; move complete value back to register

    mov A, reg[LowpassTemporal_FLOUT_CR3]   ; read power value
    and A, ~bPOWERMASK                       ; clear power bits in A
    or  A, [X]                               ; combine power value with balance of reg.
    mov reg[LowpassTemporal_FLOUT_CR3], A   ; move complete value back to register
    pop A
    RAM_EPILOGUE RAM_USE_CLASS_2
    ret

;-----------------------------------------------------------------------------
;  FUNCTION NAME: LowpassTemporal_SetCn, n=1..4
;
;  DESCRIPTION:   Alters the filter transfer function by modifying the value
;                 of the capacitors (defined in LowpassTemporal.inc)
;
;-----------------------------------------------------------------------------
;
;  ARGUMENTS:    The A register contains a non-negative integer less than 32
;  RETURNS:
;  SIDE EFFECTS: 
;    The A and X registers may be modified by this or future implementations
;    of this function.  The same is true for all RAM page pointer registers in
;    the Large Memory Model.  When necessary, it is the calling function's
;    responsibility to perserve their values across calls to fastcall16 
;    functions.
;

 LowpassTemporal_SetC1:
_LowpassTemporal_SetC1:
    RAM_PROLOGUE RAM_USE_CLASS_2
    and A, LPF_CNUMMASK                      ; mask A to protect unchanged bits
    mov X, SP                                ; define temp store location
    push A                                   ; put C1 value in temp store
    mov A, reg[LowpassTemporal_FILT_C1_REG] ; read current C1
    and A, ~LPF_CNUMMASK                     ; clear C1 bits in A
    or  A, [X]                               ; combine C1 value with balance of reg.
    mov reg[LowpassTemporal_FILT_C1_REG], A ; move complete value back to register
    pop  A
    RAM_EPILOGUE RAM_USE_CLASS_2
    ret

